import pandas as pd

def latest_login(logins: pd.DataFrame) -> pd.DataFrame:
    logins["ts"] = pd.to_datetime(logins["time_stamp"])
    l2020 = logins[(logins["ts"] >= "2020-01-01") & (logins["ts"] < "2021-01-01")]
    res = l2020.groupby("user_id", as_index=False)["time_stamp"].max()
    return res.rename(columns={"time_stamp": "last_stamp"})
